// exporter.js
// Turns a VALID parsed map into the text of a .js map file and downloads it.
//
// The generated file pushes one level onto window.LEVELS:
//   { name, mapFormatVersion, gameMap, playerStart, enemySpawns }
// gameMap is tiles[y][x] as strings, the same format the engine uses.
//
// Load the generated file(s) BEFORE engine.js.

/**
 * Builds the source text of the map file.
 * The file registers one level on window.LEVELS, so several map files can be
 * loaded side by side. Levels play in the order their <script> tags appear.
 *
 * @param {ReturnType<typeof parsePixels>} parsed - must have passed validateMap
 * @param {string} sourceName - original PNG name, used for the level name and header
 * @returns {string}
 */
function buildMapSource(parsed, sourceName = "unknown.png") {
    const { width, height, tiles, playerStarts, enemySpawns } = parsed;

    // Pad every tile name to the same width so the rows line up like a grid
    const cellWidth = Math.max(...tiles.flat().map(t => t.length)) + 2; // +2 for quotes

    const rows = tiles.map(row => {
        const last = row.length - 1;
        const cells = row.map((t, i) =>
            i < last ? `"${t}",`.padEnd(cellWidth + 2) : `"${t}"`
        );
        return "        [" + cells.join("") + "]";
    });

    const start = playerStarts[0];
    const levelName = exportFileName(sourceName).replace(/_map\.js$/, "");

    const spawns = enemySpawns.length === 0
        ? "[]"
        : "[\n" + enemySpawns.map(s => `        { x: ${s.x}, y: ${s.y} }`).join(",\n") + "\n    ]";

    return [
        `// Generated by map_compiler from ${sourceName} (${width} x ${height}).`,
        `// Do not edit by hand: change the PNG and recompile instead.`,
        `// Load this file BEFORE engine.js. Levels play in the order of their <script> tags.`,
        ``,
        `(window.LEVELS = window.LEVELS || []).push({`,
        `    name: "${levelName}",`,
        `    mapFormatVersion: 2,`,
        `    gameMap: [`,
        rows.join(",\n"),
        `    ],`,
        `    playerStart: { x: ${start.x}, y: ${start.y} },`,
        `    enemySpawns: ${spawns}`,
        `});`,
        ``
    ].join("\n");
}

/** Turns "My Level.png" into "my_level_map.js". */
function exportFileName(sourceName) {
    const base = sourceName.replace(/\.[^.]+$/, "")
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "_")
        .replace(/^_+|_+$/g, "");
    return (base || "level") + "_map.js";
}

/** Triggers a browser download of the given text. */
function downloadTextFile(filename, text) {
    const blob = new Blob([text], { type: "text/javascript" });
    const url = URL.createObjectURL(blob);

    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();

    URL.revokeObjectURL(url);
}

/**
 * Builds and downloads the map file.
 * Refuses to export a map that hasn't passed validation.
 */
function exportMap(parsed, sourceName) {
    const check = validateMap(parsed);
    if (!check.valid) {
        throw new Error("Refusing to export an invalid map: " + check.errors.map(e => e.code).join(", "));
    }

    const source = buildMapSource(parsed, sourceName);
    downloadTextFile(exportFileName(sourceName), source);
    return source;
}